-- Official SG past questions: 2025 (Reiwa 7), Questions 1–12.
-- Transcribed from IPA's published paper; correct options follow the official answer key.
-- Questions with figures/tables that cannot be represented faithfully as a single-choice item are excluded.
-- Question paper: https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/tbl5kb0000005r9r-att/2025r07_sg_qs.pdf
-- Answer key: https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/tbl5kb0000005r9r-att/2025r07_sg_ans.pdf
INSERT OR IGNORE INTO questions
  (id, track_id, topic, difficulty, question_type, prompt, options_json, answer_json, explanation, source_type, source_reference, language)
VALUES
('sg-official-r07-2025-q01','exam-sg','リスクマネジメント','standard','single_choice','JIS Q 31000:2019（リスクマネジメント－指針）におけるリスクマネジメントプロセスに関する記述のうち，適切なものはどれか。','[{"id":"a","text":"リスク対応の意義は，プロセスの設計，実施及び結末の質及び効果を保証し，改善することである。"},{"id":"b","text":"リスク特定の意義は，リスクに対処するための選択肢を選定し，実施することである。"},{"id":"c","text":"リスク評価の意義は，組織の目的の達成を助ける又は妨害する可能性のあるリスクを発見し，認識し，記述することである。"},{"id":"d","text":"リスク分析の意義は，必要に応じてリスクのレベルを含め，リスクの性質及び特徴を理解することである。"}]','"d"','正解はエ。リスク分析ではリスクの性質や特徴，必要に応じてリスクレベルを理解する。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/tbl5kb0000005r9r-att/2025r07_sg_qs.pdf','ja'),
('sg-official-r07-2025-q02','exam-sg','ログ監視・SIEM','standard','single_choice','SIEM 製品によるセキュリティ上の効果として，最も適切なものはどれか。','[{"id":"a","text":"様々な機器のログを集中管理することによって，横断的な分析や相関分析が可能になり，単純な目視だけでは発見困難な兆候を検知，分析，可視化することが可能になる。"},{"id":"b","text":"通信経路上を流れるパケットをキャプチャし，暗号化されたデータが改ざんされていないかどうかをチェックすることが可能になる。"},{"id":"c","text":"ファイアウォール，IDS，マルウェア対策といった複数のネットワークセキュリティ機能を一つの機器で実現することが可能になる。"},{"id":"d","text":"ファイルの改ざんを検知すると，事前に取得済みのバックアップを用いて直ちに修復することが可能になる。"}]','"a"','正解はア。SIEM は複数機器のログを集約し，相関分析によって脅威の兆候を検知・分析する。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/tbl5kb0000005r9r-att/2025r07_sg_qs.pdf','ja'),
('sg-official-r07-2025-q03','exam-sg','ゼロトラスト','standard','single_choice','ゼロトラストの説明として，最も適切なものはどれか。','[{"id":"a","text":"機器やソフトウェアの脆弱性のうち，開発元から対策方法，修正プログラムなどが提供されていない脆弱性が残っている状態のこと"},{"id":"b","text":"内部ネットワークであっても必ずしも安全ではないことを前提として対策を講じる考え方のこと"},{"id":"c","text":"秘密情報そのものは明かさずに，自分が秘密情報を知っていることを相手に知らせる方法のこと"},{"id":"d","text":"マルウェア定義ファイルを用いず，PC の振る舞いからマルウェア感染を検知する手法のこと"}]','"b"','正解はイ。ゼロトラストではネットワークの内外だけで信頼せず，アクセスごとに検証する考え方を採る。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/tbl5kb0000005r9r-att/2025r07_sg_qs.pdf','ja'),
('sg-official-r07-2025-q04','exam-sg','内部不正・不正のトライアングル','standard','single_choice','不正が発生する際には“不正のトライアングル”の3要素全てが存在すると考えられている。“不正のトライアングル”の構成要素の説明として，適切なものはどれか。','[{"id":"a","text":"“機会”とは，情報システムなどの技術や物理的な環境，組織のルールなど，内部者による不正行為の実行を可能又は容易にする環境の存在である。"},{"id":"b","text":"“情報と伝達”とは，必要な情報が識別，把握及び処理され，組織内外及び関係者相互に正しく伝えられるようにすることである。"},{"id":"c","text":"“正当化”とは，ノルマによるプレッシャなどのことである。"},{"id":"d","text":"“動機”とは，良心のかしゃくを乗り越える都合の良い解釈や他人への責任転嫁など，内部者が不正行為を自ら納得させるための自分勝手な理由付けである。"}]','"a"','正解はア。不正のトライアングルは動機・機会・正当化の3要素であり，機会は不正を実行しやすい環境を指す。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/tbl5kb0000005r9r-att/2025r07_sg_qs.pdf','ja'),
('sg-official-r07-2025-q05','exam-sg','DNS・キャッシュポイズニング','standard','single_choice','DNS キャッシュサーバでの DNS キャッシュポイズニング攻撃の対策はどれか。','[{"id":"a","text":"DNS サービスの待ち受けポートを 53 番に固定する。"},{"id":"b","text":"外部の DNS クライアントからの再帰的問合せを受け付けない設定にする。"},{"id":"c","text":"権威 DNS サーバへの問合せに使用するトランザクション ID を固定する。"},{"id":"d","text":"権威 DNS サーバへの非再帰的問合せを行う設定にする。"}]','"b"','正解はイ。外部からの不要な再帰問い合わせを制限し，オープンリゾルバとして悪用されるリスクを下げる。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/tbl5kb0000005r9r-att/2025r07_sg_qs.pdf','ja'),
('sg-official-r07-2025-q06','exam-sg','脆弱性評価・CVSS','standard','single_choice','CVSS v3 について，基本評価基準，現状評価基準，環境評価基準のうち，現状評価基準の特徴はどれか。','[{"id":"a","text":"攻撃コードの出現の有無，利用可能な対策のレベルなどに応じ，評価結果は時間の経過で変化する。"},{"id":"b","text":"脆弱性及び想定される脅威に応じ，製品利用者ごとに評価結果は異なる。"},{"id":"c","text":"製品利用者が脆弱性への対応を決めるための評価に用いる基準であり，評価結果は時間の経過で変化しない。"},{"id":"d","text":"評価結果は利用環境によらず同じで，かつ，時間の経過でも変化しない。"}]','"a"','正解はア。現状評価基準は攻撃コードや対策状況など時間とともに変化する要素を評価する。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/tbl5kb0000005r9r-att/2025r07_sg_qs.pdf','ja'),
('sg-official-r07-2025-q07','exam-sg','法務・特定電子メール法','standard','single_choice','特定電子メール法の説明として，適切なものはどれか。','[{"id":"a","text":"特定電子メール法は，広告のための電子メールの送信を受託した事業者だけを規制している。"},{"id":"b","text":"特定電子メール法の規制は，受信者から受信拒否の通知があった場合にだけ広告宣伝メールを禁止するオプトアウト方式を採用している。"},{"id":"c","text":"特定電子メール法の目的は，取引の公平の観点から広告宣伝メールを規制すること及び犯罪捜査のための通信傍受である。"},{"id":"d","text":"特定電子メール法は，規制の対象となる電子メールの送信者及び送信委託者に対する義務を規定している。"}]','"d"','正解はエ。特定電子メール法は対象となる送信者や送信委託者に表示義務などを定めている。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/tbl5kb0000005r9r-att/2025r07_sg_qs.pdf','ja'),
('sg-official-r07-2025-q08','exam-sg','情報セキュリティ監査・懲戒手続','standard','single_choice','情報セキュリティ違反を犯した従業員に対する懲戒手続を規定した就業規則を含む社内規程の内容について，情報セキュリティ管理基準（平成28年）に基づき監査を実施した。監査人が，指摘事項として監査報告書に記載すべきものはどれか。','[{"id":"a","text":"従業員による情報セキュリティ違反の可能性を認識したら，直ちに懲戒手続を開始することを定めていた。"},{"id":"b","text":"懲戒手続は，情報セキュリティ違反による業務への影響度，違反を犯した従業員に対する教育の実施状況などを考慮した段階別の対応を定めていた。"},{"id":"c","text":"懲戒手続は，情報セキュリティ違反を犯した従業員に対する恣意性を排除した公平な取扱いを定めていた。"},{"id":"d","text":"懲戒手続を具体化した細則を策定すること，及び従業員に周知徹底することを定めていた。"}]','"a"','正解はア。違反の可能性だけで直ちに懲戒を開始する規程は，調査や事実確認の手順を欠く点が問題となる。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/tbl5kb0000005r9r-att/2025r07_sg_qs.pdf','ja'),
('sg-official-r07-2025-q09','exam-sg','サービスマネジメント・目標達成率','standard','single_choice','サービス満足度の目標値を“サービス満足度に関する調査アンケートの満足度の平均点が5点満点中4.0点”と設定したサービスがある。調査アンケートの集計結果が次のとおりであるとき，目標達成率は幾らか。目標達成率＝満足度の平均点÷満足度の目標値。満足度（点）と回答数は，5点：50，4点：250，3点：150，2点：50，1点：0である。','[{"id":"a","text":"0.6"},{"id":"b","text":"0.72"},{"id":"c","text":"0.8"},{"id":"d","text":"0.9"}]','"d"','正解はエ。平均点は (5×50+4×250+3×150+2×50)÷500=3.6 点。3.6÷4.0=0.9。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/tbl5kb0000005r9r-att/2025r07_sg_qs.pdf','ja'),
('sg-official-r07-2025-q10','exam-sg','システム信頼性・RASIS','standard','single_choice','システムの信頼性指標である RASIS の，安全性を除く四つに関する記述のうち，適切なものはどれか。','[{"id":"a","text":"R の信頼性は，システムの MTBF によって表す。"},{"id":"b","text":"A の可用性は，システムが稼働している時間の平均値によって表す。"},{"id":"c","text":"S の保守性は，システムの稼働率によって表す。"},{"id":"d","text":"I の完全性は，システムの故障率によって表す。"}]','"a"','正解はア。R（Reliability：信頼性）は平均故障間隔 MTBF などで評価する。A は可用性，S は保守性，I は完全性を表す。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/tbl5kb0000005r9r-att/2025r07_sg_qs.pdf','ja'),
('sg-official-r07-2025-q11','exam-sg','データベース・データマート','standard','single_choice','企業全体で使用するデータを統合・整理したデータウェアハウスから，特定の分析目的のためにデータを加工して構築したものはどれか。','[{"id":"a","text":"データカタログ"},{"id":"b","text":"データマート"},{"id":"c","text":"データリネージ"},{"id":"d","text":"データレイク"}]','"b"','正解はイ。データマートは，特定の部門や分析目的に合わせてデータウェアハウスから抽出・加工したデータ集合である。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/tbl5kb0000005r9r-att/2025r07_sg_qs.pdf','ja'),
('sg-official-r07-2025-q12','exam-sg','DX・デジタルトランスフォーメーション','standard','single_choice','経済産業省が取りまとめた“DX レポート 2”では，組織が DX 実現に至る段階をデジタイゼーション，デジタライゼーション，デジタルトランスフォーメーションに分けている。製造業のデジタル化事例において，デジタルトランスフォーメーションの段階に達しているものはどれか。','[{"id":"a","text":"3D 画像撮影用の高性能カメラを生産ラインに設置し，カメラの前を通過する製造物のデジタル画像をリアルタイムで記録して，出荷検査の証拠データとする。"},{"id":"b","text":"技術継承のために，生産ラインに設置したカメラと，熟練工の手に装着したウェアラブルセンサーによって，熟練工の所作をデジタルデータとして保存した上で，AI を用いて熟練工の動きをモデル化する。"},{"id":"c","text":"顧客から販売・在庫情報を，部品メーカーから生産・在庫情報をデジタルデータで逐次入手し，AI を用いて複数の需給調整案を高速でシミュレーションすることによって，サプライチェーン全体を最適化する。"},{"id":"d","text":"生産ラインで取得したデジタル画像データから良品，不良品の特徴を AI に学習させた上で，AI で画像解析を行うことによって，自社の出荷時検品作業を効率化する。"}]','"c"','正解はウ。顧客と部品メーカーを含むサプライチェーン全体を最適化し，組織横断の業務や価値提供を変革している。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/tbl5kb0000005r9r-att/2025r07_sg_qs.pdf','ja');
